import React, { useState } from 'react';
import { Link } from 'react-router'; // IMPORTANT : Permet de changer de page sans recharger
import '../Styles/style.css';

export default function Navbar() {
    const [isOpen, setIsOpen] = useState(false);

    return (
        <>
            <nav className="navbar">
                <div onClick={() => setIsOpen(!isOpen)}>
                <Link to="/" className="nav-logo" >
                    MonLogo
                </Link>
                </div>

                <button
                    className={`hamburger ${isOpen ? 'open' : ''}`}
                    onClick={() => setIsOpen(!isOpen)}
                    aria-label="Menu de navigation"
                >
                    <span className="bar"></span>
                    <span className="bar"></span>
                    <span className="bar"></span>
                </button>

                <div className={`nav-links ${isOpen ? 'active' : ''}`}>
                    <Link to="/page1" onClick={() => setIsOpen(!isOpen)}>Page 1</Link>
                    <Link to="/page2" onClick={() => setIsOpen(!isOpen)}>Page 2</Link>
                </div>
            </nav>

            {isOpen && <div className="menu-overlay" onClick={() => setIsOpen(!isOpen)}></div>}
        </>
    );
}
